'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let p = 0;

const E = input[p++];
const R = input[p++];

const edges = new Array(R);
const adj = Array.from({ length: E }, () => []);

for (let i = 0; i < R; i++) {
  const a = input[p++] - 1;
  const b = input[p++] - 1;
  const w = input[p++];
  edges[i] = { a, b, w };
  adj[a].push({ to: b, id: i, w });
  adj[b].push({ to: a, id: i, w });
}

// Find bridges iteratively.
const disc = new Int32Array(E);
const low = new Int32Array(E);
const parent = new Int32Array(E);
const parentEdge = new Int32Array(E);
const nextIndex = new Int32Array(E);
const bridge = new Uint8Array(R);
let timer = 0;

for (let root = 0; root < E; root++) {
  if (disc[root]) continue;

  parent[root] = -1;
  parentEdge[root] = -1;
  disc[root] = low[root] = ++timer;
  const stack = [root];

  while (stack.length) {
    const u = stack[stack.length - 1];

    if (nextIndex[u] < adj[u].length) {
      const edge = adj[u][nextIndex[u]++];
      if (edge.id === parentEdge[u]) continue;

      const v = edge.to;
      if (!disc[v]) {
        parent[v] = u;
        parentEdge[v] = edge.id;
        disc[v] = low[v] = ++timer;
        stack.push(v);
      } else {
        low[u] = Math.min(low[u], disc[v]);
      }
    } else {
      stack.pop();
      if (parent[u] !== -1) {
        const par = parent[u];
        low[par] = Math.min(low[par], low[u]);
        if (low[u] > disc[par]) bridge[parentEdge[u]] = 1;
      }
    }
  }
}

// The non-bridge edges form the cycles.
const cycleLength = new Float64Array(E);
const seenVertex = new Uint8Array(E);
const seenEdge = new Uint8Array(R);

for (let i = 0; i < R; i++) {
  if (bridge[i] || seenEdge[i]) continue;

  const vertices = [];
  const stack = [edges[i].a];
  let length = 0;
  seenVertex[edges[i].a] = 1;

  while (stack.length) {
    const u = stack.pop();
    vertices.push(u);

    for (const edge of adj[u]) {
      if (bridge[edge.id]) continue;

      if (!seenEdge[edge.id]) {
        seenEdge[edge.id] = 1;
        length += edge.w;
      }

      if (!seenVertex[edge.to]) {
        seenVertex[edge.to] = 1;
        stack.push(edge.to);
      }
    }
  }

  for (const v of vertices) cycleLength[v] = length;
}

class MinHeap {
  constructor() {
    this.nodes = [];
    this.values = [];
  }

  push(node, value) {
    let i = this.nodes.length;
    this.nodes.push(node);
    this.values.push(value);

    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (this.values[parent] <= value) break;
      this.nodes[i] = this.nodes[parent];
      this.values[i] = this.values[parent];
      i = parent;
    }

    this.nodes[i] = node;
    this.values[i] = value;
  }

  pop() {
    const node = this.nodes[0];
    const value = this.values[0];
    const lastNode = this.nodes.pop();
    const lastValue = this.values.pop();

    if (this.nodes.length) {
      let i = 0;
      while (true) {
        let child = i * 2 + 1;
        if (child >= this.nodes.length) break;
        if (child + 1 < this.nodes.length && this.values[child + 1] < this.values[child]) {
          child++;
        }
        if (this.values[child] >= lastValue) break;
        this.nodes[i] = this.nodes[child];
        this.values[i] = this.values[child];
        i = child;
      }
      this.nodes[i] = lastNode;
      this.values[i] = lastValue;
    }

    return [node, value];
  }

  get size() {
    return this.nodes.length;
  }
}

const K = input[p++];
const answers = [];

for (let q = 0; q < K; q++) {
  const x = input[p++] - 1;
  const trainLength = input[p++];

  const dist = new Float64Array(E);
  dist.fill(Infinity);
  const heap = new MinHeap();

  for (let v = 0; v < E; v++) {
    if (cycleLength[v] >= trainLength) {
      dist[v] = cycleLength[v];
      heap.push(v, dist[v]);
    }
  }

  while (heap.size) {
    const [u, d] = heap.pop();
    if (d !== dist[u]) continue;

    for (const edge of adj[u]) {
      const nd = d + 2 * edge.w;
      if (nd < dist[edge.to]) {
        dist[edge.to] = nd;
        heap.push(edge.to, nd);
      }
    }
  }

  answers.push(Number.isFinite(dist[x]) ? String(dist[x]) : '-1');
}

console.log(answers.join('\n'));
